  updateAccountSecret(
    description: $description
    expiresAt: $expiresAt
    name: $name
    scope: $scope
    value: $value
  ) {
    __typename
    # secret # The secret that was updated
  }
}

mutation deleteAccountSecret($name: String!) {
  deleteAccountSecret(name: $name) {
    __typename
    deleted
  }
}
